// Consolida items do Bluefleet em 1 item para
// disparar o próximo nó (PG) apenas uma vez.
// Dados originais acessíveis via $('Buscar Veículos Bluefleet').all()
const total = $input.all().length;
console.log('[INFO] Veículos recebidos do Bluefleet: ' + total);
return [{ json: { totalBluefleet: total } }];

// ========================================================
// Detectar Mudanças — SCD Tipo 2
// Compara dados novos (Bluefleet) com estado atual (dim_veiculo)
// Gera SQL para: histórico (mudanças) + upsert (estado atual)
// ========================================================
const bluefleet = $('Buscar Veículos Bluefleet').all();
const atuais = $input.all();

// Mapa do estado atual: placa → dados
const mapAtual = {};
for (const item of atuais) {
  const placa = (item.json.placa || '').toUpperCase().trim();
  if (placa) mapAtual[placa] = item.json;
}

const esc = (v) => v != null ? String(v).replace(/'/g, "''") : '';

// Formata valor para SQL: NULL literal quando ausente, aspas para strings
const sqlStr  = (v) => v != null && v !== '' ? "'" + esc(v) + "'" : 'NULL';
const sqlNum  = (v) => v != null && v !== '' ? Number(v)         : 'NULL';
const sqlDate = (v) => v != null && v !== '' ? "'" + esc(v) + "'" : 'NULL';

let sqlHist = '';
let countMudancas = 0;
let countNovos = 0;
const upsertValues = [];
const detalhes = [];  // log de mudanças para debug

for (const item of bluefleet) {
  const placa = (item.json.placa || '').trim().toUpperCase().replace(/[\s-]/g, '');
  if (!placa) continue;

  const filialNova    = (item.json.filial_operacional || '').trim();
  const situacaoNova  = (item.json.situacao_veiculo   || '').trim();
  const modeloRaw     = (item.json.modelo_raw          || '').trim();

  // Novos campos técnicos
  const tanqueLitros                 = sqlNum(item.json.tanque_litros);
  const anoModelo                    = sqlNum(item.json.ano_modelo);
  const anoFabricacao                = sqlNum(item.json.ano_fabricacao);
  const montadora                    = sqlStr(item.json.montadora);
  const odometroConfirmado           = sqlNum(item.json.odometro_confirmado);
  const ultimaManutencao             = sqlDate(item.json.ultima_manutencao);
  const ultimaManutencaoPreventiva   = sqlDate(item.json.ultima_manutencao_preventiva);
  const kmUltimaManutencaoPreventiva = sqlNum(item.json.km_ultima_manutencao_preventiva);

  const atual = mapAtual[placa];

  if (!atual) {
    // Veículo novo — primeiro registro no histórico
    countNovos++;
    sqlHist += "INSERT INTO torre.gold_hist_veiculo "
      + "(placa, filial_operacional, situacao_veiculo, valido_de, atual) VALUES ("
      + "'" + esc(placa) + "', "
      + "'" + esc(filialNova) + "', "
      + "'" + esc(situacaoNova) + "', "
      + "CURRENT_DATE, TRUE) "
      + "ON CONFLICT (placa) WHERE atual = TRUE DO NOTHING;\n";
  } else {
    // Veículo existe — verificar mudanças
    const mudouFilial    = (atual.filial_operacional || '').trim() !== filialNova;
    const mudouSituacao  = (atual.situacao_veiculo   || '').trim() !== situacaoNova;

    if (mudouFilial || mudouSituacao) {
      countMudancas++;
      detalhes.push(placa + ': '
        + (mudouFilial   ? 'filial ['    + (atual.filial_operacional||'') + ' → ' + filialNova   + '] ' : '')
        + (mudouSituacao ? 'situacao ['  + (atual.situacao_veiculo  ||'') + ' → ' + situacaoNova + ']'  : ''));

      // Fechar registro anterior
      sqlHist += "UPDATE torre.gold_hist_veiculo SET "
        + "valido_ate = CURRENT_DATE - INTERVAL '1 day', "
        + "atual = FALSE "
        + "WHERE placa = '" + esc(placa) + "' AND atual = TRUE;\n";

      // Abrir novo registro
      sqlHist += "INSERT INTO torre.gold_hist_veiculo "
        + "(placa, filial_operacional, situacao_veiculo, valido_de, atual) VALUES ("
        + "'" + esc(placa) + "', "
        + "'" + esc(filialNova) + "', "
        + "'" + esc(situacaoNova) + "', "
        + "CURRENT_DATE, TRUE);\n";
    }
  }

  // Upsert value para dim_veiculo (todos os campos)
  upsertValues.push(
    "('" + esc(placa) + "', "
    + "'" + esc(modeloRaw) + "', "
    + "torre.gold_classificar_veiculo('" + esc(modeloRaw) + "'), "
    + "'" + esc(filialNova) + "', "
    + "'" + esc(situacaoNova) + "', "
    + tanqueLitros + ", "
    + anoModelo + ", "
    + anoFabricacao + ", "
    + montadora + ", "
    + odometroConfirmado + ", "
    + ultimaManutencao + ", "
    + ultimaManutencaoPreventiva + ", "
    + kmUltimaManutencaoPreventiva + ", "
    + "NOW())"
  );
}

// Build batched upsert SQL
let sqlUpsert = '';
const chunkSize = 500;
for (let i = 0; i < upsertValues.length; i += chunkSize) {
  const chunk = upsertValues.slice(i, i + chunkSize);
  sqlUpsert += "INSERT INTO torre.gold_dim_veiculo\n"
    + "  (placa, modelo_raw, grupo_veiculo, filial_operacional, situacao_veiculo,\n"
    + "   tanque_litros, ano_modelo, ano_fabricacao, montadora,\n"
    + "   odometro_confirmado, ultima_manutencao, ultima_manutencao_preventiva,\n"
    + "   km_ultima_manutencao_preventiva, atualizado_em)\n"
    + "VALUES\n"
    + chunk.join(",\n")
    + "\nON CONFLICT (placa) DO UPDATE SET\n"
    + "  modelo_raw                       = EXCLUDED.modelo_raw,\n"
    + "  grupo_veiculo                    = torre.gold_classificar_veiculo(EXCLUDED.modelo_raw),\n"
    + "  filial_operacional               = EXCLUDED.filial_operacional,\n"
    + "  situacao_veiculo                 = EXCLUDED.situacao_veiculo,\n"
    + "  tanque_litros                    = EXCLUDED.tanque_litros,\n"
    + "  ano_modelo                       = EXCLUDED.ano_modelo,\n"
    + "  ano_fabricacao                   = EXCLUDED.ano_fabricacao,\n"
    + "  montadora                        = EXCLUDED.montadora,\n"
    + "  odometro_confirmado              = EXCLUDED.odometro_confirmado,\n"
    + "  ultima_manutencao                = EXCLUDED.ultima_manutencao,\n"
    + "  ultima_manutencao_preventiva     = EXCLUDED.ultima_manutencao_preventiva,\n"
    + "  km_ultima_manutencao_preventiva  = EXCLUDED.km_ultima_manutencao_preventiva,\n"
    + "  atualizado_em                    = NOW();\n";
}

if (!sqlHist) sqlHist = "SELECT 'Nenhuma mudança detectada no histórico' AS status;";

console.log('[INFO] Total Bluefleet: ' + bluefleet.length
  + ' | Estado atual: ' + atuais.length
  + ' | Novos: ' + countNovos
  + ' | Mudanças: ' + countMudancas);
if (detalhes.length > 0) {
  console.log('[MUDANÇAS] ' + detalhes.join(' | '));
}

return [{
  json: {
    sqlHist,
    sqlUpsert,
    totalProcessados: bluefleet.length,
    totalEstadoAtual: atuais.length,
    totalNovos: countNovos,
    totalMudancas: countMudancas,
    detalhes: detalhes
  }
}];
